// Secret Guard: the counterpart of Blast Radius for secrets. Stops before Claude
//  - writes an API key, token or private key into a file (Write, Edit, MultiEdit, NotebookEdit),
//  - writes or `git add`s a .env, .pem, id_rsa & co. that git does not ignore,
//  - commits while a secret sits in the staged changes,
//  - redirects a secret from the command line into a file.
// Mode "block" refuses the action (Claude gets the reason), "warn" only reports.
//
// Exceptions, so test keys and example files pass:
//  - project: .secretguard-allow in the project root (can be committed, applies to the team),
//  - global: in the box's store (all projects).
// An entry is a path in gitignore style (tests/fixtures/**, *.example.ts) or a value as
// sha256:<hex>, so no secret ever stands in clear text in an exception list. Placeholders
// (EXAMPLE, DUMMY, FAKE, xxxx …) pass on their own (option); that covers the documentation keys
// of AWS too, which all contain "EXAMPLE".
// Only the person changes the exceptions (window /secret-allow); Claude writing the list is stopped.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BlockedFind } from '../types'
import { PATTERNS, isPlaceholder } from './patterns'

type Hit = { what: string; where: string; path: string | null; value: string | null; hard?: boolean }

const blocked = atom({ plugin: 'mod-box', key: 'sw_blocked' } as const, [] as BlockedFind[])
const projectLines = atom({ plugin: 'mod-box', key: 'sw_project' } as const, [] as string[])
const globalLines = atom({ plugin: 'mod-box', key: 'sw_global' } as const, [] as string[])

export const ALLOW_FILE = '.secretguard-allow'
const STORE_GLOBAL = 'secret-allow-global'
const PANE = 'mod-box-secret-allow'
const MAX_BLOCKED = 20

// Display language and options (module level: the pane and the checks read them).
let lang: 'de' | 'en' = 'en'
const t = (de: string, en: string) => (lang === 'en' ? en : de)
let placeholders = true
let isWindows = false

// still exported here for the tests and older imports
export { PATTERNS, isPlaceholder }

// Files that hold secrets; templates (.example, .sample, .template, .dist) are fine.
export const SECRET_FILE = /(^|[\\/])(\.env(\.[\w-]+)?|[^\\/]*\.(pem|key|p12|pfx|keystore|jks)|id_(rsa|dsa|ecdsa|ed25519)|credentials(\.json)?|\.npmrc|\.pypirc|\.netrc)$/i
const TEMPLATE = /\.(example|sample|template|dist)$/i

export function findSecrets(text: string, where: string, path: string | null = null): Hit[] {
  const hits: Hit[] = []
  for (const [what, re] of PATTERNS) {
    for (const m of text.matchAll(re)) hits.push({ what, where, path, value: m[0] })
  }
  return hits
}

export function isSecretFile(file: string): boolean {
  return SECRET_FILE.test(file) && !TEMPLATE.test(file)
}

// Paths of a `git add …`; "." and "-A" count as "everything".
export function gitAddPaths(command: string): string[] | 'all' | null {
  const m = /(?:^|[;&|]\s*)git\s+(?:-C\s+\S+\s+)?add\s+([^;&|]*)/.exec(command)
  if (!m) return null
  const words = (m[1] ?? '').trim().split(/\s+/).filter(Boolean)
  if (words.some(w => w === '.' || w === '-A' || w === '--all' || w === '*')) return 'all'
  return words.filter(w => !w.startsWith('-'))
}

// ---------------------------------------------------------------- exceptions

/** An exception line: a path pattern, or sha256:<hex>. Comments after # are dropped. */
export function parseAllow(lines: string[]): { globs: string[]; hashes: Set<string> } {
  const globs: string[] = []
  const hashes = new Set<string>()
  for (const raw of lines) {
    const line = raw.replace(/\s+#.*$/, '').replace(/^#.*$/, '').trim()
    if (!line) continue
    const h = /^sha256:([0-9a-f]{64})$/i.exec(line)
    if (h) hashes.add(h[1]!.toLowerCase())
    else globs.push(line)
  }
  return { globs, hashes }
}

/** gitignore-like matching: no slash = any folder level; a slash = from the project root; ** spans folders. */
export function globMatch(glob: string, path: string, ignoreCase = false): boolean {
  let g = glob.trim().replace(/\\/g, '/')
  if (!g) return false
  const dirOnly = g.endsWith('/')
  if (dirOnly) g = g.slice(0, -1)
  const anchored = g.startsWith('/') || g.includes('/')
  g = g.replace(/^\//, '')
  let re = ''
  for (let i = 0; i < g.length; i++) {
    const c = g[i]!
    if (c === '*' && g[i + 1] === '*') {
      re += '.*'
      i++
      if (g[i + 1] === '/') i++
    } else if (c === '*') re += '[^/]*'
    else if (c === '?') re += '[^/]'
    else re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  }
  const body = anchored ? `^${re}` : `(^|.*/)${re}`
  return new RegExp(`${body}(/.*)?$`, ignoreCase ? 'i' : '').test(path.replace(/\\/g, '/').replace(/^\.\//, ''))
}

export async function sha256(text: string): Promise<string> {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('')
}

async function projectRoot($: EngineInterface): Promise<string> {
  return (await $.session.cwd()).replace(/\\/g, '/').replace(/\/$/, '')
}

function relative(root: string, file: string): string {
  const f = file.replace(/\\/g, '/')
  const r = root + '/'
  if (isWindows ? f.toLowerCase().startsWith(r.toLowerCase()) : f.startsWith(r)) return f.slice(r.length)
  return f.replace(/^\.\//, '')
}

let projectCache: { path: string; mtime: number; lines: string[] } | null = null

async function loadProjectLines($: EngineInterface): Promise<string[]> {
  const file = `${await projectRoot($)}/${ALLOW_FILE}`
  const st = await $.fs.stat(file).catch(() => null)
  if (!st) {
    projectCache = { path: file, mtime: 0, lines: [] }
    return []
  }
  if (projectCache && projectCache.path === file && projectCache.mtime === st.mtimeMs) return projectCache.lines
  const lines = String(await $.fs.read(file).catch(() => '')).split(/\r?\n/)
  projectCache = { path: file, mtime: st.mtimeMs, lines }
  return lines
}

async function loadGlobalLines($: EngineInterface): Promise<string[]> {
  const saved = await $.store.get(STORE_GLOBAL).catch(() => null)
  return Array.isArray(saved) ? saved.filter((x): x is string => typeof x === 'string') : []
}

/** Drops the hits an exception covers. */
async function applyExceptions($: EngineInterface, hits: Hit[]): Promise<Hit[]> {
  if (hits.length === 0) return hits
  const all = parseAllow([...(await loadProjectLines($)), ...(await loadGlobalLines($))])
  const out: Hit[] = []
  for (const h of hits) {
    if (h.hard) {
      out.push(h)
      continue
    }
    if (h.path && all.globs.some(g => globMatch(g, h.path!, isWindows))) continue
    if (h.value) {
      if (placeholders && isPlaceholder(h.value)) continue
      if (all.hashes.has(await sha256(h.value))) continue
    }
    out.push(h)
  }
  return out
}

// ---------------------------------------------------------------- the guard

export const register: Register = (on, options) => {
  const mode = options.mode === 'warn' ? 'warn' : 'block'
  lang = options.language === 'de' ? 'de' : 'en'
  placeholders = options.placeholders !== 'off'

  on('session.start', {}, async ($, e, next) => {
    const r = await next(e)
    isWindows = (await $.env.get('OS')) === 'Windows_NT'
    await $.command.register({ name: 'secret-allow', description: t('Secret-Wächter: Ausnahmen verwalten', 'Secret Guard: manage exceptions') })
    return r
  })

  on('command.run', { command: 'secret-allow' }, async $ => {
    await refreshLists($)
    await $.ui.open({ id: PANE, title: t('Secret-Wächter · Ausnahmen', 'Secret Guard · exceptions'), focus: true, closeOnEscape: true })
    return { text: t('Ausnahmen des Secret-Wächters geöffnet.', 'Secret Guard exceptions opened.') }
  })

  on('tool.call', {}, async ($, e, next) => {
    const found = await check($, e as unknown as Record<string, unknown>)
    const hits = dedupe(await applyExceptions($, found))
    if (hits.length === 0) return next(e)
    const list = hits.map(h => `${h.what} (${h.where})`).join('; ')
    const isHard = hits.some(h => h.hard)
    await remember($, hits, mode === 'block' || isHard)
    if (mode === 'warn' && !isHard) {
      $.ui.toast(`${t('Secret-Wächter', 'Secret Guard')}: ${list}`)
      return next(e)
    }
    $.ui.toast(`${t('Secret-Wächter hat angehalten', 'Secret Guard stopped')}: ${list} · /secret-allow`)
    return {
      deny: isHard
        ? `Secret Guard stopped this: ${list}. The exception list ${ALLOW_FILE} is changed only by the user, through the Mod Box window (/secret-allow). Do not try to change it another way.`
        : `Secret Guard stopped this action: ${list}. Secrets do not belong in files in the repository or in commits. ` +
          'Use an environment variable or a file that is not versioned (in .gitignore), and write a placeholder instead. ' +
          `If this is a known test key or an example file, the user can allow it with /secret-allow; do not edit ${ALLOW_FILE} yourself. ` +
          'Do not retry it another way unless the user explicitly asks.',
    }
  })
  // No .catch: if the check itself fails (no git, say), the action goes on rather than blocking every edit.

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => drawPane($, e))
}

async function check($: EngineInterface, e: Record<string, unknown>): Promise<Hit[]> {
  const tool = String(e.tool)
  const root = await projectRoot($)
  const file = typeof e.file_path === 'string' ? e.file_path : typeof e.notebook_path === 'string' ? e.notebook_path : ''
  if (tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit' || tool === 'NotebookEdit') {
    const rel = relative(root, file)
    const where = file.split(/[\\/]/).pop() || file
    // The exception list belongs to the person.
    if (where === ALLOW_FILE) return [{ what: t('Änderung der Ausnahmeliste', 'change of the exception list'), where, path: rel, value: null, hard: true }]
    const texts: string[] = []
    if (typeof e.content === 'string') texts.push(e.content)
    if (typeof e.new_string === 'string') texts.push(e.new_string)
    if (typeof e.new_source === 'string') texts.push(e.new_source)
    if (Array.isArray(e.edits)) for (const x of e.edits) if (x && typeof x.new_string === 'string') texts.push(x.new_string)
    const hits = texts.flatMap(text => findSecrets(text, where, rel))
    // A .env may hold secrets when git ignores it.
    if (isSecretFile(file)) {
      if (await isIgnored($, file)) return []
      hits.push({ what: t('Geheimnis-Datei, die git nicht ignoriert', 'secret file that git does not ignore'), where, path: rel, value: null })
    }
    return hits
  }
  if (tool === 'Bash' && typeof e.command === 'string') {
    const cmd = e.command
    const hits: Hit[] = []
    if (cmd.includes(ALLOW_FILE) && /(>|\btee\b|\bsed\s+-i|\brm\b|\bmv\b|\bcp\b|Set-Content|Add-Content|Out-File|Remove-Item|\btruncate\b)/.test(cmd)) {
      hits.push({ what: t('Änderung der Ausnahmeliste', 'change of the exception list'), where: ALLOW_FILE, path: ALLOW_FILE, value: null, hard: true })
    }
    const add = gitAddPaths(cmd)
    if (add && add !== 'all') for (const p of add) if (isSecretFile(p)) hits.push({ what: t('git add einer Geheimnis-Datei', 'git add of a secret file'), where: p, path: relative(root, p), value: null })
    if (add === 'all') {
      // What "git add ." would take: changed and new files that are not ignored.
      const r = await $.process.run(['git', 'status', '--porcelain', '--untracked-files=all']).catch(() => null)
      for (const line of r?.exitCode === 0 ? r.stdout.split('\n') : []) {
        const p = line.slice(3).trim().replace(/^"|"$/g, '')
        if (p && isSecretFile(p)) hits.push({ what: t('git add . würde eine Geheimnis-Datei aufnehmen', 'git add . would stage a secret file'), where: p, path: p, value: null })
      }
    }
    if (/(?:^|[;&|]\s*)git\s+(?:-C\s+\S+\s+)?commit\b/.test(cmd)) {
      const staged = await $.process.run(['git', 'diff', '--cached', '--name-only']).catch(() => null)
      for (const p of staged?.exitCode === 0 ? staged.stdout.split('\n').filter(Boolean) : []) {
        if (isSecretFile(p)) hits.push({ what: t('Commit mit einer Geheimnis-Datei', 'commit with a secret file'), where: p, path: p, value: null })
      }
      const diff = await $.process.run(['git', 'diff', '--cached', '-U0', '--no-color']).catch(() => null)
      if (diff?.exitCode === 0) hits.push(...secretsInDiff(diff.stdout))
    }
    // A secret on the command line that is redirected into a file (echo KEY > file).
    const target = /(?:>>?|\btee\s+(?:-a\s+)?)\s*(["']?)([^\s"';&|]+)\1/.exec(cmd)
    if (target) hits.push(...findSecrets(cmd, t('Umleitung in eine Datei', 'redirect into a file'), relative(root, target[2]!)))
    return hits
  }
  return []
}

/** Added lines of a staged diff, per file, so path exceptions apply. */
export function secretsInDiff(diff: string): Hit[] {
  const hits: Hit[] = []
  let path: string | null = null
  let added: string[] = []
  const flush = () => {
    if (path && added.length) hits.push(...findSecrets(added.join('\n'), path, path))
    added = []
  }
  for (const line of diff.split('\n')) {
    if (line.startsWith('+++ ')) {
      flush()
      path = line.slice(4).replace(/^b\//, '').trim()
      if (path === '/dev/null') path = null
    } else if (line.startsWith('+') && !line.startsWith('+++')) added.push(line.slice(1))
  }
  flush()
  return hits
}

async function isIgnored($: EngineInterface, file: string): Promise<boolean> {
  const r = await $.process.run(['git', 'check-ignore', '-q', file]).catch(() => null)
  return r?.exitCode === 0
}

function dedupe(hits: Hit[]): Hit[] {
  const seen = new Set<string>()
  return hits.filter(h => {
    const k = `${h.what}|${h.where}|${h.value ?? ''}`
    if (seen.has(k)) return false
    seen.add(k)
    return true
  })
}

// Keeps the last finds for the window (hash only, never the value).
async function remember($: EngineInterface, hits: Hit[], stopped: boolean) {
  const now = await $.clock.now()
  const finds: BlockedFind[] = []
  for (const h of hits) {
    if (h.hard) continue
    finds.push({ at: now, what: h.what, where: h.where, path: h.path, hash: h.value ? await sha256(h.value) : null, stopped })
  }
  if (finds.length) await update($, blocked, list => [...finds, ...list].slice(0, MAX_BLOCKED)).catch(() => {})
}

// ---------------------------------------------------------------- the exceptions window

async function refreshLists($: EngineInterface) {
  projectCache = null
  const lines = await loadProjectLines($)
  await update($, projectLines, () => lines.filter(l => l.trim() !== ''))
  const g = await loadGlobalLines($)
  await update($, globalLines, () => g)
}

async function addEntry($: EngineInterface, scope: 'project' | 'global', entry: string) {
  const line = entry.trim()
  if (!line) return
  if (scope === 'global') {
    const list = await loadGlobalLines($)
    if (!list.includes(line)) await $.store.set(STORE_GLOBAL, [...list, line])
  } else {
    const file = `${await projectRoot($)}/${ALLOW_FILE}`
    const existing = await $.fs.read(file).then(String).catch(() => '')
    const header = existing ? '' : `# ${t('Ausnahmen für den Secret-Wächter der Mod Box: Pfade (gitignore-Stil) oder sha256:<hash> eines Werts.', 'Exceptions for the Mod Box Secret Guard: paths (gitignore style) or sha256:<hash> of a value.')}\n`
    const lines = existing.split(/\r?\n/)
    if (!lines.some(l => l.replace(/\s+#.*$/, '').trim() === line.replace(/\s+#.*$/, '').trim())) {
      await $.fs.write(file, (existing ? existing.replace(/\s*$/, '\n') : header) + line + '\n')
    }
  }
  $.ui.toast(t(`Ausnahme hinzugefügt (${scope === 'global' ? 'global' : ALLOW_FILE}).`, `Exception added (${scope === 'global' ? 'global' : ALLOW_FILE}).`))
  await refreshLists($)
}

async function removeEntry($: EngineInterface, scope: 'project' | 'global', entry: string) {
  if (scope === 'global') {
    await $.store.set(STORE_GLOBAL, (await loadGlobalLines($)).filter(l => l !== entry))
  } else {
    const file = `${await projectRoot($)}/${ALLOW_FILE}`
    const existing = await $.fs.read(file).then(String).catch(() => '')
    await $.fs.write(file, existing.split(/\r?\n/).filter(l => l !== entry).join('\n'))
  }
  await refreshLists($)
}

async function drawPane($: EngineInterface, e: any) {
  const { Box, Text, Button, Input } = $.ui.resolve(e) as any
  const finds = await read($, blocked)
  const proj = await read($, projectLines)
  const glob = await read($, globalLines)
  const when = (ms: number) => new Date(ms).toLocaleTimeString(lang === 'en' ? 'en-GB' : 'de-DE', { hour: '2-digit', minute: '2-digit' })
  const entryRow = (scope: 'project' | 'global', line: string, i: number) =>
    line.trim().startsWith('#') ? (
      <Text key={`${scope}-c-${i}`} dimColor>{`  ${line}`}</Text>
    ) : (
      <Box key={`${scope}-${i}`} flexDirection="row">
        <Text>{`  ${line.length > 90 ? line.slice(0, 89) + '…' : line}`}</Text>
        <Text>{'  '}</Text>
        <Button key={`sa-rm-${scope}-${i}`} label={t('Entfernen', 'Remove')} plain onPress={() => void removeEntry($, scope, line)} />
      </Box>
    )
  return (
    <Box flexDirection="column" paddingX={1}>
      <Text dimColor wrap="wrap">
        {t(
          `Ausnahmen lassen bekannte Test-Schlüssel und Beispieldateien durch. Einträge: ein Pfad im gitignore-Stil (tests/fixtures/**, *.example.ts) oder sha256:<hash> eines Werts – Schlüssel stehen nie im Klartext in der Liste. Projekt-Ausnahmen liegen in ${ALLOW_FILE} (kann ins Repo), globale gelten überall. Claude kann die Liste nicht ändern.`,
          `Exceptions let known test keys and example files pass. Entries: a path in gitignore style (tests/fixtures/**, *.example.ts) or sha256:<hash> of a value – keys never stand in clear text in the list. Project exceptions live in ${ALLOW_FILE} (can be committed), global ones apply everywhere. Claude cannot change the list.`,
        )}
      </Text>

      <Box flexDirection="column" marginTop={1}>
        <Text bold>{t('Zuletzt gefunden', 'Last finds')}</Text>
        {finds.length === 0 ? <Text dimColor>{t('  Noch nichts.', '  Nothing yet.')}</Text> : null}
        {finds.map((f, i) => (
          <Box key={`sa-f-${i}`} flexDirection="column">
            <Text>
              <Text color={f.stopped ? 'red' : 'yellow'}>{`  ${f.stopped ? '✘' : '⚠'} ${f.what}`}</Text>
              <Text dimColor>{`  ${f.path ?? f.where} · ${when(f.at)}`}</Text>
            </Text>
            <Box flexDirection="row" paddingLeft={4}>
              {f.path ? <Button key={`sa-fp-${i}`} label={t('Datei erlauben (Projekt)', 'Allow file (project)')} plain onPress={() => void addEntry($, 'project', f.path!)} /> : null}
              {f.path && f.hash ? <Text>{'  '}</Text> : null}
              {f.hash ? <Button key={`sa-fv-${i}`} label={t('Wert erlauben (Projekt)', 'Allow value (project)')} plain onPress={() => void addEntry($, 'project', `sha256:${f.hash}  # ${f.what} ${f.path ?? f.where}`)} /> : null}
              {f.hash ? <Text>{'  '}</Text> : null}
              {f.hash ? <Button key={`sa-fg-${i}`} label={t('Wert erlauben (global)', 'Allow value (global)')} plain onPress={() => void addEntry($, 'global', `sha256:${f.hash}  # ${f.what}`)} /> : null}
            </Box>
          </Box>
        ))}
      </Box>

      <Box flexDirection="column" marginTop={1}>
        <Text bold>{t(`Projekt (${ALLOW_FILE})`, `Project (${ALLOW_FILE})`)}</Text>
        {proj.filter(l => !l.trim().startsWith('#')).length === 0 ? <Text dimColor>{t('  keine', '  none')}</Text> : null}
        {proj.map((l, i) => entryRow('project', l, i))}
        {Input ? <Input key="sa-add-project" label={t('  Neu: ', '  New: ')} placeholder="tests/fixtures/**" submitLabel={t('Hinzufügen', 'Add')} onSubmit={(v: string) => void addEntry($, 'project', v)} /> : null}
      </Box>

      <Box flexDirection="column" marginTop={1}>
        <Text bold>{t('Global (alle Projekte)', 'Global (all projects)')}</Text>
        {glob.length === 0 ? <Text dimColor>{t('  keine', '  none')}</Text> : null}
        {glob.map((l, i) => entryRow('global', l, i))}
        {Input ? <Input key="sa-add-global" label={t('  Neu: ', '  New: ')} placeholder="*.example.env" submitLabel={t('Hinzufügen', 'Add')} onSubmit={(v: string) => void addEntry($, 'global', v)} /> : null}
      </Box>

      <Text dimColor>{placeholders ? t('Platzhalter (EXAMPLE, DUMMY, FAKE, xxxx …) werden automatisch durchgelassen.', 'Placeholders (EXAMPLE, DUMMY, FAKE, xxxx …) pass automatically.') : t('Platzhalter-Erkennung ist aus.', 'Placeholder detection is off.')}</Text>
    </Box>
  )
}

files.mods/screen-mask/hooks/register.tsx:
// Screen Mask: while you share your screen, the transcript hides API keys, tokens, private keys,
// e-mail addresses, IP addresses, your login name in paths and any names you list. Only the
// drawing changes: Claude still reads and writes the original text. Nothing leaves the machine.
// /mask switches it; the band shows when it is on.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { offer as offerBand } from '../../settings/hooks/band'
import type { BandPart } from '../../settings/hooks/band'
import { type MaskRules, maskDeep, maskText, parseTerms } from './mask'

const isOn = atom({ plugin: 'mod-box', key: 'sm_on' } as const, false)
// Kept across sessions: a restart in the middle of a screen share must not uncover anything.
const STORE_ON = 'sm:on'

let lang: 'de' | 'en' = 'en'
const t = (de: string, en: string) => (lang === 'en' ? en : de)
const rules: MaskRules = { terms: [], user: '', emails: true, ips: true }

const mask = (s: string) => maskText(s, rules)

async function setOn($: EngineInterface, on: boolean) {
  await update($, isOn, () => on)
  await $.store.set(STORE_ON, on).catch(() => {})
  $.ui.toast(on ? t('🙈 Bildschirmschutz an: Geheimnisse und Namen sind in der Anzeige verdeckt.', '🙈 Screen mask on: secrets and names are hidden on screen.') : t('Bildschirmschutz aus.', 'Screen mask off.'))
}

export const register: Register = (on, options) => {
  lang = options.language === 'de' ? 'de' : 'en'
  rules.terms = parseTerms(String(options.terms ?? ''))
  rules.emails = String(options.emails ?? 'on') !== 'off'
  rules.ips = String(options.ips ?? 'on') !== 'off'

  on('session.start', {}, async ($, e, next) => {
    const r = await next(e)
    rules.user = String((await $.env.get('USERNAME')) || (await $.env.get('USER')) || '')
    await $.command.register({ name: 'mask', description: t('Bildschirmschutz: Geheimnisse und Namen in der Anzeige verdecken', 'Screen mask: hide secrets and names on screen'), argumentHint: '[on|off]' })
    if ((await $.store.get(STORE_ON).catch(() => false)) === true) await update($, isOn, () => true)
    return r
  })

  on('command.run', { command: 'mask' }, async ($, e) => {
    const arg = String(e.args ?? '').trim().toLowerCase()
    const want = arg === 'on' || arg === 'an' ? true : arg === 'off' || arg === 'aus' ? false : !(await read($, isOn))
    await setOn($, want)
    return { text: want ? t('Bildschirmschutz an.', 'Screen mask on.') : t('Bildschirmschutz aus.', 'Screen mask off.') }
  })

  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    if (!(await read($, isOn))) return next(e)
    return next({ ...e, props: { ...e.props, text: mask(e.props.text) } })
  })

  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    if (!(await read($, isOn))) return next(e)
    return next({ ...e, props: { ...e.props, text: mask(e.props.text) } })
  })

  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    if (!(await read($, isOn))) return next(e)
    const props = e.props as Record<string, unknown>
    return next({ ...e, props: { ...e.props, input: maskDeep(props.input, mask), ...(props.output === undefined ? {} : { output: maskDeep(props.output, mask) }) } } as typeof e)
  })

  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (!(await read($, isOn))) return next(e)
    const props = e.props as Record<string, unknown>
    return next({ ...e, props: { ...e.props, output: maskDeep(props.output, mask) } } as typeof e)
  })

  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    if (!(await read($, isOn))) return next(e)
    return next({ ...e, props: { ...e.props, calls: e.props.calls.map(c => ({ ...c, input: maskDeep((c as Record<string, unknown>).input, mask) })) } } as typeof e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const rest = await next(e)
    if (!e.props.hasSurvey) {
      const part = await band($, e).catch(() => null)
      if (part) offerBand(e, part)
    }
    return rest
  })
}

export async function band($: EngineInterface, e: any): Promise<BandPart | null> {
  if (!(await read($, isOn))) return null
  const { Text, Button } = $.ui.resolve(e)
  const what = [t('Geheimnisse', 'secrets'), rules.emails ? t('E-Mails', 'e-mails') : '', rules.ips ? 'IPs' : '', rules.user ? t('Benutzername', 'login name') : '', rules.terms.length ? t(`${rules.terms.length} Begriffe`, `${rules.terms.length} terms`) : ''].filter(Boolean).join(', ')
  return {
    id: 'screenMask',
    urgent: false,
    short: <Text color="yellow">🙈</Text>,
    line: (
      <Text>
        <Text color="yellow" bold>{'🙈 '}</Text>
        <Text>{t('Bildschirmschutz an: ', 'Screen mask on: ')}</Text>
        <Text dimColor>{what}</Text>
      </Text>
    ),
    actions: [<Button key="sm-off" label={t('Aus', 'Off')} plain onPress={() => void setOn($, false)} />],
    status: `🙈 ${t('Bildschirmschutz', 'Screen mask')}`,
  }
}

files.mods/package-guard/hooks/register.tsx:
// Package Guard: before Claude installs (or runs, via npx and the like) a package from npm, PyPI or
// crates.io, it asks the public registry about it. It holds the command when the package does not
// exist (a made-up name), is only days old, or looks like a well-known package and is young or thin
// (typosquatting). Everything else goes through untouched. The person allows a held package in
// the band; Claude then installs it again.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { PackageHold, PackageInfo } from '../types'
import { offer as offerBand } from '../../settings/hooks/band'
import type { BandPart } from '../../settings/hooks/band'
import { type Ecosystem, wantedPackages } from './parse'
import { lookalike } from './similar'

const hold = atom({ plugin: 'mod-box', key: 'pg_hold' } as const, null as PackageHold | null)
const allowed = atom({ plugin: 'mod-box', key: 'pg_allowed' } as const, [] as string[])

let lang: 'de' | 'en' = 'en'
const t = (de: string, en: string) => (lang === 'en' ? en : de)
let mode = 'block'
const known = new Map<string, PackageInfo>()

const DAY = 86_400_000
const NEW_DAYS = 14
const YOUNG_DAYS = 180
const FEW_VERSIONS = 5

/** Why a package is suspicious; empty when it is fine. Pure, for the tests. */
export function reasonsFor(eco: Ecosystem, name: string, info: PackageInfo | null, now: number, de = false): string[] {
  const tr = (a: string, b: string) => (de ? a : b)
  const like = lookalike(eco, name)
  if (!info || info.error) return like ? [tr(`ähnelt „${like}“ (Registry nicht erreichbar)`, `looks like "${like}" (registry not reachable)`)] : []
  if (info.exists === false) return [tr('gibt es in der Registry nicht (erfundener Name?)', 'does not exist in the registry (a made-up name?)')]
  // npm replaces removed malware with "0.0.1-security" from npm/security-holder.
  if (/-security$/.test(info.latest ?? '') || /security-holder/.test(info.repo ?? '')) {
    return [tr('wurde als Schadpaket entfernt (npm-Sicherheitsplatzhalter)', 'was removed as malware (npm security placeholder)')]
  }
  const out: string[] = []
  const days = info.created ? Math.floor((now - Date.parse(info.created)) / DAY) : NaN
  // a date in the future means a wrong clock: no age then
  const age = Number.isFinite(days) && days >= 0 ? days : null
  if (age !== null && age < NEW_DAYS) out.push(tr(`erst ${age} Tag(e) alt`, `only ${age} day(s) old`))
  if (like && ((age !== null && age < YOUNG_DAYS) || (info.versions ?? 0) < FEW_VERSIONS)) {
    out.push(tr(`ähnelt „${like}“ (${info.versions ?? '?'} Versionen, ${age ?? '?'} Tage alt)`, `looks like "${like}" (${info.versions ?? '?'} versions, ${age ?? '?'} days old)`))
  }
  return out
}

async function lookup($: EngineInterface, eco: Ecosystem, name: string): Promise<PackageInfo | null> {
  const key = `${eco}:${name}`
  const cached = known.get(key)
  if (cached) return cached
  const script = `${$.plugin.root}/mods/package-guard/registry.mjs`.replace(/\\/g, '/')
  const r = await $.process.run(['node', script, eco, name], { timeoutMs: 15_000 }).catch(() => null)
  let info: PackageInfo | null = null
  try {
    info = JSON.parse((r?.stdout ?? '').trim().split('\n').pop() || 'null') as PackageInfo | null
  } catch {
    info = null
  }
  if (info && !info.error) known.set(key, info)
  return info
}

const label = (eco: Ecosystem) => (eco === 'npm' ? 'npm' : eco === 'pypi' ? 'PyPI' : 'crates.io')

export const register: Register = (on, options) => {
  lang = options.language === 'de' ? 'de' : 'en'
  mode = String(options.mode ?? 'block')

  on('session.start', {}, async ($, e, next) => {
    const r = await next(e)
    await $.command.register({ name: 'pkg-allow', description: t('Paket-Wächter: ein angehaltenes Paket erlauben', 'Package Guard: allow a held package'), argumentHint: '<name>' })
    return r
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const wanted = wantedPackages(String(e.command ?? ''))
    if (!wanted.length) return next(e)
    const ok = await read($, allowed)
    const now = await $.clock.now()
    const held: PackageHold['packages'] = []
    for (const p of wanted) {
      if (ok.includes(`${p.eco}:${p.name}`)) continue
      const info = await lookup($, p.eco, p.name)
      const reasons = reasonsFor(p.eco, p.name, info, now, lang === 'de')
      if (reasons.length) held.push({ eco: p.eco, name: p.name, runs: p.runs, reasons, repo: info?.repo ?? null })
    }
    if (!held.length) return next(e)
    const list = held.map(p => `${p.name} (${label(p.eco)}): ${p.reasons.join(', ')}`).join('; ')
    // Without a registry answer a look-alike is only worth a warning.
    const onlyUnsure = held.every(p => p.reasons.every(r => /registry not reachable|Registry nicht erreichbar/.test(r)))
    if (mode === 'warn' || onlyUnsure) {
      $.ui.toast(`📦 ${t('Paket-Wächter', 'Package Guard')}: ${list}`, { timeoutMs: 8000 })
      return next(e)
    }
    await update($, hold, () => ({ command: String(e.command ?? '').slice(0, 300), packages: held, at: now, isDismissed: false }))
    $.ui.toast(`📦 ${t('Paket-Wächter hat angehalten', 'Package Guard held')}: ${list}`, { timeoutMs: 8000 })
    return {
      deny:
        `Package Guard held this command and did not run it: ${list}. ` +
        'Check the name: it may be a typo of a well-known package or a package that does not exist. ' +
        'Tell the user what you found. If they confirm the package, they allow it in the band above the prompt (or with /pkg-allow <name>); then run the command again. Do not install it another way.',
    }
  })

  on('command.run', { command: 'pkg-allow' }, async ($, e) => {
    const name = String(e.args ?? '').trim().toLowerCase()
    const h = await read($, hold)
    const hits = (h?.packages ?? []).filter(p => !name || p.name === name)
    if (!hits.length) return { text: t('Kein angehaltenes Paket dieses Namens.', 'No held package by that name.') }
    await allow($, hits.map(p => `${p.eco}:${p.name}`))
    return { text: t(`Erlaubt: ${hits.map(p => p.name).join(', ')}. Claude kann den Befehl jetzt erneut ausführen.`, `Allowed: ${hits.map(p => p.name).join(', ')}. Claude can run the command again now.`) }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const rest = await next(e)
    if (!e.props.hasSurvey) {
      const part = await band($, e).catch(() => null)
      if (part) offerBand(e, part)
    }
    return rest
  })
}

async function allow($: EngineInterface, keys: string[]) {
  await update($, allowed, list => [...new Set([...list, ...keys])])
  await update($, hold, h => {
    if (!h) return h
    const rest = h.packages.filter(p => !keys.includes(`${p.eco}:${p.name}`))
    return rest.length ? { ...h, packages: rest } : null
  })
}

export async function band($: EngineInterface, e: any): Promise<BandPart | null> {
  const h = await read($, hold)
  if (!h || h.isDismissed || !h.packages.length) return null
  const { Text, Button } = $.ui.resolve(e)
  const names = h.packages.map(p => `${p.name} (${label(p.eco)}): ${p.reasons.join(', ')}`).join(' · ')
  const keys = h.packages.map(p => `${p.eco}:${p.name}`)
  return {
    id: 'packageGuard',
    urgent: true,
    short: <Text color="yellow">{`📦 ${h.packages.length}`}</Text>,
    line: (
      <Text>
        <Text color="yellow" bold>{'📦 '}</Text>
        <Text>{t('Paket angehalten: ', 'Package held: ')}</Text>
        <Text dimColor>{names}</Text>
      </Text>
    ),
    actions: [
      <Button key="pg-allow" label={t('Erlauben', 'Allow')} plain onPress={() => void allow($, keys).then(() => $.ui.toast(t('Erlaubt. Claude kann den Befehl jetzt erneut ausführen.', 'Allowed. Claude can run the command again now.')))} />,
      <Button key="pg-dismiss" label="×" plain onPress={() => void update($, hold, x => (x ? { ...x, isDismissed: true } : x))} />,
    ],
    status: `📦 ${names}`,
  }
}

files.mods/ci-watch/hooks/register.tsx:
// CI watch: "A push you don't check on doesn't count as done."
// After every successful `git push` (Bash tool) it polls the GitHub Actions runs for the
// pushed commit via gh until all are done. A band above the prompt shows the status;
// on red it fetches `gh run view --log-failed`, opens a window with the log and/or puts
// an analysis request into the prompt (nothing is sent by itself). /ci shows the status.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { CiRun, CiWatch } from '../types'
import { offer as offerBand } from '../../settings/hooks/band'
import type { BandPart } from '../../settings/hooks/band'

const watch = atom({ plugin: 'mod-box', key: 'ci_watch' } as const, null as CiWatch | null)
const PANE = 'ci-watch'
const NO_RUNS_AFTER_MS = 120_000 // how long GitHub may take to create a run
const GIVE_UP_AFTER_MS = 3 * 60 * 60_000
const LOG_LINES = 200

export const PUSH = /(?:^|[;&|(]\s*)git\s+(?:-C\s+(\S+)\s+)?push\b/

// Settings and timers at module level: the validator requires $ to be passed only to
// top-level functions.
let intervalMs = 20_000
let onRed = 'both'
let withSound = false
let notifyOn = 'red'
let prOnDesktop = 'app'
let onDesktop = false

export const PR_CREATE = /(?:^|[;&|(]\s*)gh\s+pr\s+create\b/
export const PR_URL = /https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/pull\/(\d+)/

/** owner/repo of a pull request's URL, for gh -R; '' for anything else. Pure. */
export function repoOf(url: string): string {
  return /^https:\/\/github\.com\/([\w.-]+\/[\w.-]+)\/pull\/\d+/.exec(url)?.[1] ?? ''
}

// gh finds a pull request by its URL from any folder; by its number only inside its repository
// (a PR made from another folder or a worktree is watched from the session's folder).
const prRef = (pr: { number: number; url: string }) => pr.url || String(pr.number)
// Display language (options.language: de | en)
let lang: 'de' | 'en' = 'en'
const t = (de: string, en: string) => (lang === 'en' ? en : de)
let timer: Timer | null = null

function stop() {
  timer?.cancel()
  timer = null
}

function start($: EngineInterface) {
  stop()
  timer = $.clock.every(intervalMs, () => void poll($).catch(() => {}))
  void poll($).catch(() => {})
}

async function poll($: EngineInterface) {
  const w = await read($, watch)
  if (!w || (w.phase !== 'warte' && w.phase !== 'laeuft')) return stop()
  const now = await $.clock.now()
  const fetched = w.pr ? await prChecks($, w) : await commitRuns($, w)
  if (typeof fetched === 'string') {
    await set($, x => ({ ...x, phase: 'fehler', message: fetched, endedAt: now }))
    return stop()
  }
  const runs = fetched
  if (runs.length === 0) {
    if (now - w.startedAt > NO_RUNS_AFTER_MS) {
      await set($, x => ({ ...x, phase: 'keine', message: t('Kein Actions-Lauf zu diesem Commit.', 'No Actions run for this commit.'), endedAt: now }))
      stop()
    }
    return
  }
  const open = runs.filter(x => x.status !== 'completed')
  if (open.length > 0) {
    await set($, x => ({ ...x, phase: 'laeuft', runs }))
    if (now - w.startedAt > GIVE_UP_AFTER_MS) {
      await set($, x => ({ ...x, phase: 'fehler', message: t('Nach 3 Stunden nicht fertig; Überwachung beendet.', 'Not finished after 3 hours; stopped watching.'), endedAt: now }))
      stop()
    }
    return
  }
  const bad = runs.find(x => !['success', 'skipped', 'neutral'].includes(x.conclusion))
  stop()
  if (!bad) {
    const merge = w.pr ? await mergeState($, w) : ''
    await set($, x => ({ ...x, phase: 'gruen', runs, endedAt: now, message: '', pr: x.pr ? { ...x.pr, merge } : null }))
    $.ui.toast(
      w.pr
        ? t(`PR #${w.pr.number}: alle ${runs.length} Checks grün${merge ? ` · ${merge}` : ''}`, `PR #${w.pr.number}: all ${runs.length} checks green${merge ? ` · ${merge}` : ''}`)
        : t(`CI grün: ${runs.length} Lauf/Läufe für ${w.sha.slice(0, 7)}`, `CI green: ${runs.length} run(s) for ${w.sha.slice(0, 7)}`),
    )
    void sound($, 'green')
    void notify($, 'green', w.pr ? `PR #${w.pr.number}: ${t('alle Checks grün', 'all checks green')}` : `${w.branch} ${w.sha.slice(0, 7)}: ${t('alle Läufe grün', 'all runs green')}`)
    return
  }
  const log = bad.id ? await $.process.run(['gh', 'run', 'view', String(bad.id), '--log-failed', ...(w.pr && repoOf(w.pr.url) ? ['-R', repoOf(w.pr.url)] : [])], { cwd: w.cwd, timeoutMs: 60_000 }).catch(() => null) : null
  const tail = (log?.stdout ?? '').split('\n').slice(-LOG_LINES).join('\n').trim()
  const noLog = bad.id
    ? t('(kein Log erhalten)', '(no log received)')
    : t(`(Check außerhalb von GitHub Actions: kein Log über gh. Details: ${bad.url})`, `(check outside GitHub Actions: no log through gh. Details: ${bad.url})`)
  await set($, x => ({ ...x, phase: 'rot', runs, endedAt: now, failed: { id: bad.id, name: bad.name, url: bad.url, log: tail || noLog } }))
  void sound($, 'red')
  void notify($, 'red', `${bad.name} (${bad.conclusion}) · ${w.pr ? `PR #${w.pr.number}` : w.branch}`)
  $.ui.toast(t(`CI rot: ${bad.name} (${bad.conclusion}). Analysieren, bevor irgendetwas anderes passiert.`, `CI red: ${bad.name} (${bad.conclusion}). Analyse it before anything else happens.`))
  if (onRed === 'pane' || onRed === 'both') void $.ui.open({ id: PANE, title: `${t('CI rot', 'CI red')} · ${bad.name}`, focus: true, closeOnEscape: true }).catch(() => {})
  if (onRed === 'prompt' || onRed === 'both') void $.prompt.fill({ text: analyse(w, bad), mode: 'replace' }).catch(() => {})
}

async function startAfterPush($: EngineInterface, dashC: string | undefined, command: string) {
  if (await begin($, dashC, command)) start($)
}

function ghError(stderr: string): string {
  return /not found|nicht gefunden|ENOENT|cannot find/i.test(stderr)
    ? t('gh ist nicht installiert.', 'gh is not installed.')
    : /auth|login/i.test(stderr)
      ? t('gh ist nicht angemeldet (gh auth login).', 'gh is not signed in (gh auth login).')
      : stderr.trim().split('\n')[0] || t('gh-Fehler', 'gh error')
}

// The Actions runs of the pushed commit; a message when gh fails.
async function commitRuns($: EngineInterface, w: CiWatch): Promise<CiRun[] | string> {
  const r = await $.process
    .run(['gh', 'run', 'list', '--commit', w.sha, '--json', 'databaseId,name,workflowName,status,conclusion,url', '--limit', '30'], { cwd: w.cwd, timeoutMs: 30_000 })
    .catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
  if (r.exitCode !== 0) return ghError(r.stderr)
  return (JSON.parse(r.stdout || '[]') as Array<Record<string, unknown>>).map(x => ({
    id: Number(x.databaseId),
    name: String(x.workflowName || x.name || 'Lauf'),
    status: String(x.status ?? ''),
    conclusion: String(x.conclusion ?? ''),
    url: String(x.url ?? ''),
  }))
}

/** gh pr checks --json: bucket pass|fail|pending|skipping|cancel; exit 8 while pending, 1 on failure. */
export function parseChecks(stdout: string): CiRun[] {
  const list = JSON.parse(stdout || '[]') as Array<Record<string, unknown>>
  return list.map(x => {
    const bucket = String(x.bucket ?? '')
    const link = String(x.link ?? '')
    const run = /\/actions\/runs\/(\d+)/.exec(link)
    return {
      id: run ? Number(run[1]) : 0,
      name: x.workflow ? `${String(x.workflow)} / ${String(x.name ?? '')}` : String(x.name ?? 'Check'),
      status: bucket === 'pending' ? 'in_progress' : 'completed',
      conclusion: bucket === 'pass' ? 'success' : bucket === 'skipping' ? 'skipped' : bucket === 'fail' ? 'failure' : bucket === 'cancel' ? 'cancelled' : bucket,
      url: link,
    }
  })
}

// The checks of a pull request: Actions and every other check (other CI, bots).
async function prChecks($: EngineInterface, w: CiWatch): Promise<CiRun[] | string> {
  const r = await $.process
    .run(['gh', 'pr', 'checks', prRef(w.pr!), '--json', 'name,state,bucket,link,workflow'], { cwd: w.cwd, timeoutMs: 30_000 })
    .catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
  if (r.stdout.trim().startsWith('[')) return parseChecks(r.stdout)
  if (/no checks reported/i.test(r.stderr)) return []
  return ghError(r.stderr)
}

// After green: can the PR be merged? (mergeStateStatus and reviewDecision of gh pr view)
async function mergeState($: EngineInterface, w: CiWatch): Promise<string> {
  const r = await $.process
    .run(['gh', 'pr', 'view', prRef(w.pr!), '--json', 'mergeStateStatus,reviewDecision,isDraft,state'], { cwd: w.cwd, timeoutMs: 30_000 })
    .catch(() => null)
  if (!r || r.exitCode !== 0) return ''
  return mergeText(JSON.parse(r.stdout || '{}'))
}

export function mergeText(v: { mergeStateStatus?: string; reviewDecision?: string; isDraft?: boolean; state?: string }): string {
  if (v.state && v.state !== 'OPEN') return v.state === 'MERGED' ? t('schon gemergt', 'already merged') : t('geschlossen', 'closed')
  if (v.isDraft) return t('noch Entwurf', 'still a draft')
  if (v.reviewDecision === 'CHANGES_REQUESTED') return t('Änderungen angefordert', 'changes requested')
  if (v.reviewDecision === 'REVIEW_REQUIRED') return t('wartet auf Review', 'waiting for review')
  switch (v.mergeStateStatus) {
    case 'CLEAN':
    case 'HAS_HOOKS':
      return t('bereit zum Mergen', 'ready to merge')
    case 'DIRTY':
      return t('Merge-Konflikte', 'merge conflicts')
    case 'BEHIND':
      return t('Branch ist hinter der Basis', 'branch is behind its base')
    case 'BLOCKED':
      return t('blockiert (Regeln des Repos)', 'blocked (repo rules)')
    case 'UNSTABLE':
      return t('nicht alle Pflicht-Checks grün', 'not all required checks green')
    default:
      return ''
  }
}

// Starts watching a pull request: its number or URL, in the folder cwd.
async function beginPr($: EngineInterface, ref: string, cwd: string): Promise<boolean> {
  // No ref: the pull request of the current branch.
  const r = await $.process.run(['gh', 'pr', 'view', ...(ref ? [ref] : []), '--json', 'number,url,title,headRefName,headRefOid,state'], { cwd, timeoutMs: 30_000 }).catch(() => null)
  if (!r || r.exitCode !== 0) return false
  const v = JSON.parse(r.stdout || '{}') as { number?: number; url?: string; title?: string; headRefName?: string; headRefOid?: string; state?: string }
  if (!v.number || v.state !== 'OPEN') return false
  const now = await $.clock.now()
  await update($, watch, (): CiWatch => ({
    sha: String(v.headRefOid ?? ''),
    branch: String(v.headRefName ?? '?'),
    cwd,
    startedAt: now,
    endedAt: 0,
    phase: 'warte',
    runs: [],
    failed: null,
    message: '',
    isDismissed: false,
    pr: { number: Number(v.number), url: String(v.url ?? ''), title: String(v.title ?? ''), merge: '' },
  }))
  return true
}

async function startPr($: EngineInterface, ref: string, cwd: string): Promise<boolean> {
  const ok = await beginPr($, ref, cwd)
  if (ok) start($)
  return ok
}

// A system notification at the end (option notify: off | red | always), through the person's own
// notification channel. Claude Code notifies when a turn ends; a CI run usually ends later.
async function notify($: EngineInterface, kind: 'green' | 'red', text: string) {
  if (notifyOn === 'off' || (notifyOn === 'red' && kind === 'green')) return
  await $.ui.notify(text, { title: kind === 'red' ? t('CI rot', 'CI red') : t('CI grün', 'CI green') }).catch(() => undefined)
}

// A short sound at the end (option): Windows system sounds through PowerShell, elsewhere the mod's own clip.
async function sound($: EngineInterface, kind: 'green' | 'red') {
  if (!withSound) return
  if ((await $.env.get('OS')) === 'Windows_NT') {
    const s = kind === 'green' ? 'Asterisk' : 'Hand'
    await $.process.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', `[System.Media.SystemSounds]::${s}.Play(); Start-Sleep -Milliseconds 900`], { timeoutMs: 10_000 }).catch(() => {})
  } else {
    await $.audio.play({ asset: `mods/ci-watch/sounds/${kind}.wav` }).catch(() => {})
  }
}

export const register: Register = (on, options) => {
  // Band manager: hand this mod’s display to the Mod Box (it draws, orders and places it).
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const rest = await next(e)
    if (!e.props.hasSurvey) {
      const part = await band($, e).catch(() => null)
      if (part) offerBand(e, part)
    }
    return rest
  })

  intervalMs = Math.max(5, Number(options.intervalSec) || 20) * 1000
  onRed = String(options.onRed || 'both')
  withSound = options.sound === 'on'
  notifyOn = String(options.notify || 'red')
  prOnDesktop = String(options.prOnDesktop || 'app')
  lang = options.language === 'de' ? 'de' : 'en'

  on('session.start', {}, async ($, e, next) => {
    const r = await next(e)
    onDesktop = (e as { surface?: string | null }).surface === 'desktop'
    await $.command.register({
      name: 'ci',
      description: t('CI-Wächter: Stand der Läufe zum letzten Push oder PR', 'CI Watch: state of the runs for the last push or PR'),
      argumentHint: '[pr <nr|url> | stop]',
    })
    // Watching continues after a reload.
    const w = await read($, watch)
    if (w && (w.phase === 'warte' || w.phase === 'laeuft')) start($)
    return r
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const result = await next(e)
    if (('deny' in result && result.deny !== undefined) || result.isError) return result
    const cmd = String(e.command ?? '')
    // A new pull request: its URL stands in the output of gh pr create.
    if (PR_CREATE.test(cmd)) {
      const url = PR_URL.exec(String(result.text ?? ''))?.[0]
      // The desktop app binds a new PR to the session and watches its checks itself (CI bar, auto-fix).
      if (url && onDesktop && prOnDesktop === 'app') $.ui.toast(t('PR-Checks überwacht die Desktop-App (CI-Leiste); /ci pr zeigt sie hier.', 'The desktop app watches the PR checks (CI bar); /ci pr shows them here.'))
      else if (url) void startPr($, url, await $.session.cwd()).catch(() => {})
      return result
    }
    const m = PUSH.exec(cmd)
    if (!m) return result
    if (/\bpush\b[^;&|]*(?:--dry-run|\s-n\b)/.test(cmd)) return result
    void startAfterPush($, m[1], cmd).catch(() => {})
    return result
  })

  on('command.run', { command: 'ci' }, async ($, e) => {
    const args = String(e.args ?? '').trim().split(/\s+/).filter(Boolean)
    if (args[0] === 'stop') {
      stop()
      await update($, watch, () => null)
      return { text: t('CI-Wächter: Beobachtung beendet.', 'CI Watch: stopped watching.') }
    }
    if (args[0] === 'pr') {
      const ref = args[1] ?? ''
      const ok = ref ? await startPr($, ref, await $.session.cwd()) : await startPr($, '', await $.session.cwd())
      return {
        text: ok
          ? t(`CI-Wächter: beobachte PR ${ref || '(Branch)'}.`, `CI Watch: watching PR ${ref || '(branch)'}.`)
          : t('CI-Wächter: kein offener PR gefunden (/ci pr <Nummer oder URL>).', 'CI Watch: no open PR found (/ci pr <number or URL>).'),
      }
    }
    const w = await read($, watch)
    if (!w) return { text: t('CI-Wächter: noch kein Push in dieser Sitzung. /ci pr <Nummer> beobachtet einen PR.', 'CI Watch: no push in this session yet. /ci pr <number> watches a PR.') }
    if (w.phase === 'rot') await $.ui.open({ id: PANE, title: `${t('CI rot', 'CI red')} · ${w.failed?.name ?? ''}`, focus: true, closeOnEscape: true })
    await update($, watch, x => (x ? { ...x, isDismissed: false } : x))
    return { text: `${t('CI-Wächter', 'CI Watch')}: ${summary(w)}` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Code } = $.ui.resolve(e) as any
    const w = await read($, watch)
    const f = w?.failed
    if (!w || !f) return <Text dimColor>{t('Kein roter Lauf.', 'No red run.')}</Text>
    const rows = Math.max(5, (e.viewport?.rows ?? 30) - 8)
    return (
      <Box flexDirection="column" paddingX={1}>
        <Text>
          <Text color="red" bold>{`✘ ${f.name}`}</Text>
          <Text dimColor>{w.pr ? `  ·  PR #${w.pr.number} ${w.pr.title}` : `  ·  ${w.branch}@${w.sha.slice(0, 7)}`}</Text>
        </Text>
        <Text dimColor>{f.url}</Text>
        <Box marginTop={1} flexDirection="column">
          {Code ? <Code source={f.log.split('\n').slice(-rows).join('\n')} wrap="truncate-end" /> : <Text>{f.log.split('\n').slice(-rows).join('\n')}</Text>}
        </Box>
        <Box flexDirection="row" marginTop={1}>
          <Button key="ci-p-analyse" label={t('Analysieren lassen', 'Have it analysed')} variant="primary" autoFocus onPress={() => void $.prompt.fill({ text: analyse(w, f), mode: 'replace' }).then(() => $.ui.close({ id: PANE }))} />
          <Text>{'  '}</Text>
          <Button key="ci-p-kopieren" label={t('Log kopieren', 'Copy log')} onPress={(press: { surface?: string }) => void $.ui.copy({ text: f.log, surface: press.surface as any })} />
          <Text>{'  '}</Text>
          <Button key="ci-p-zu" label={t('Schließen', 'Close')} role="dismiss" onPress={() => void $.ui.close({ id: PANE })} />
        </Box>
      </Box>
    )
  })
}

async function set($: EngineInterface, fn: (w: CiWatch) => CiWatch) {
  await update($, watch, w => (w ? fn(w) : w))
}

async function begin($: EngineInterface, dashC: string | undefined, command: string): Promise<boolean> {
  const base = await $.session.cwd()
  const cd = /(?:^|[;&|]\s*)cd\s+("[^"]+"|'[^']+'|\S+)\s*&&[^;|]*git\s+(?:-C\s+\S+\s+)?push/.exec(command)?.[1]?.replace(/^["']|["']$/g, '')
  const dir = dashC ?? cd
  const cwd = dir ? (/^([a-zA-Z]:[\\/]|\/)/.test(dir) ? dir : `${base}/${dir}`) : base
  const head = await $.process.run(['git', 'rev-parse', 'HEAD'], { cwd }).catch(() => null)
  if (!head || head.exitCode !== 0) return false
  const branch = await $.process.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD'], { cwd }).catch(() => null)
  // Has the branch an open pull request? Then its checks count (also other CI and bots).
  if (await beginPr($, branch?.stdout.trim() || '', cwd)) return true
  const now = await $.clock.now()
  await update($, watch, (): CiWatch => ({
    sha: head.stdout.trim(),
    branch: branch?.stdout.trim() || '?',
    cwd,
    startedAt: now,
    endedAt: 0,
    phase: 'warte',
    runs: [],
    failed: null,
    message: '',
    isDismissed: false,
    pr: null,
  }))
  return true
}

export function summary(w: CiWatch): string {
  const ref = w.pr ? `PR #${w.pr.number}` : `${w.branch}@${w.sha.slice(0, 7)}`
  const took = w.endedAt && w.startedAt ? ` in ${fmt(w.endedAt - w.startedAt)}` : ''
  switch (w.phase) {
    case 'warte':
      return `${ref}: ${t('warte auf GitHub Actions …', 'waiting for GitHub Actions …')}`
    case 'laeuft': {
      const done = w.runs.filter(r => r.status === 'completed').length
      return `${ref}: ${t(`${w.runs.length - done} laufen, ${done} fertig`, `${w.runs.length - done} running, ${done} done`)} (${w.runs.map(r => r.name).join(', ')})`
    }
    case 'gruen':
      return w.pr
        ? `${ref}: ${t(`${w.runs.length} Checks grün`, `${w.runs.length} checks green`)}${took}${w.pr.merge ? ` · ${w.pr.merge}` : ''}`
        : `${ref}: ${t(`grün, ${w.runs.length} Lauf/Läufe`, `green, ${w.runs.length} run(s)`)}${took}`
    case 'rot':
      return `${ref}: ${t('rot in', 'red in')} ${w.failed?.name ?? '?'}${took}`
    case 'keine':
      return `${ref}: ${w.message}`
    case 'fehler':
      return `${ref}: ${w.message}`
  }
}

function fmt(ms: number): string {
  const s = Math.round(ms / 1000)
  return s >= 60 ? `${Math.floor(s / 60)}m${String(s % 60).padStart(2, '0')}s` : `${s}s`
}

// The request Claude gets is English; only the answer follows the language setting.
export function analyse(w: CiWatch, f: { id: number; name: string; url: string }): string {
  const what = w.pr ? `PR #${w.pr.number} (${w.pr.url})` : `${w.branch}@${w.sha.slice(0, 7)}`
  const answerIn = lang === 'en' ? '' : ' Answer in German.'
  if (!f.id) {
    // A check outside GitHub Actions: no log through gh, only its link.
    return `CI is red for ${what}: check "${f.name}" (${f.url}) failed; it does not run in GitHub Actions. Open its details, name the cause and whether it lies in the code, in the setup or in something external, then propose the fix before anything else happens.${answerIn}`
  }
  return (
    `CI is red: run "${f.name}" for ${w.branch}@${w.sha.slice(0, 7)} (${f.url}). ` +
    `Read the logs of the failed step (gh run view ${f.id} --log-failed), name the cause ` +
    'and say whether it lies in the code, in the fixture or in something external. If external: should the test withstand it? ' +
    `Then propose the fix, before anything else happens.${answerIn}`
  )
}

// For the Mod Box band manager (instead of an AbovePrompt hook of its own).
export async function band($: EngineInterface, e: any): Promise<BandPart | null> {
  const w = await read($, watch)
  if (!w || w.isDismissed) return null
  const { Text, Button } = $.ui.resolve(e)
  const color = w.phase === 'gruen' ? 'green' : w.phase === 'rot' ? 'red' : w.phase === 'fehler' ? 'yellow' : 'cyan'
  const icon = w.phase === 'gruen' ? '✔' : w.phase === 'rot' ? '✘' : w.phase === 'fehler' || w.phase === 'keine' ? '·' : '⏳'
  const isDone = w.phase !== 'warte' && w.phase !== 'laeuft'
  const actions: unknown[] = []
  if (w.phase === 'rot') {
    actions.push(<Button key="ci-log" label="Log" plain onPress={() => void $.ui.open({ id: PANE, title: `${t('CI rot', 'CI red')} · ${w.failed?.name ?? ''}`, focus: true, closeOnEscape: true })} />)
    if (w.failed) actions.push(<Button key="ci-analyse" label={t('Analysieren', 'Analyse')} plain onPress={() => void $.prompt.fill({ text: analyse(w, w.failed!), mode: 'replace' })} />)
  }
  if (isDone) actions.push(<Button key="ci-weg" label="×" plain onPress={() => void update($, watch, x => (x ? { ...x, isDismissed: true } : x))} />)
  return {
    id: 'ciWatch',
    urgent: w.phase === 'rot' || w.phase === 'fehler',
    short: (
      <Text>
        <Text color={color} bold>{`CI ${icon}`}</Text>
        <Text dimColor>{` ${w.pr ? `#${w.pr.number} ` : ''}${w.phase === 'laeuft' ? `${w.runs.filter(r => r.status === 'completed').length}/${w.runs.length}` : w.phase === 'gruen' ? (w.pr?.merge || t('grün', 'green')) : w.phase === 'warte' ? '…' : w.pr ? '' : w.branch}`}</Text>
      </Text>
    ),
    line: (
      <Text>
        <Text color={color} bold>{`CI ${icon} `}</Text>
        <Text>{summary(w)}</Text>
      </Text>
    ),
    actions,
    status: `CI ${icon} ${summary(w)}`,
  }
}

